import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    static void shuffle(long arr[]){
        Random rnd = new Random();
        for(int i=arr.length-1;i>0;i--){
            int idx = rnd.nextInt(i+1);
            long tmp = arr[idx];
            arr[idx] = arr[i];
            arr[i] = tmp;
        }
        
    }
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		Scanner sc = new Scanner(System.in);
		int T = sc.nextInt();
		StringBuilder sb = new StringBuilder();
		while(T-- > 0){
		    int n = sc.nextInt();
		    int m = 3*n;
		    long arr[] = new long[m];
		    for(int i=0;i<m;i++){
		        arr[i] = sc.nextLong();
		    }
		    shuffle(arr);
		    Arrays.sort(arr);
		    long a[] = new long[m+1];
		    for(int i=0;i<m;i++){
		        a[i+1] = arr[m-1-i];
		    }
		    long p[] = new long[m+1];
		    for(int i=1;i<=m;i++){
		        p[i] = p[i-1]+a[i];
		    }
		    long mx = 0;
		    for(int k=0;k<=n;k++){
		        int l = 0, h = n-k-1;
		        int best = 0;
		        while(l <= h){
		            int mi = (l + h) >>> 1;
		            long d = a[k+2*mi+1] + a[k+2*mi+2] - 3L * a[3*n-2*k-mi];
		            if(d >= 0){
		                best = mi + 1;
		                l = mi + 1;
		            }else{
		                h = mi - 1;
		            }
		        }
		        long curr = 2L*p[k] + p[k+2*best] + 3L*p[3*n-2*k-best];
		        if(curr > mx){
		            mx = curr;
		        }
		    }
		    sb.append(mx).append('\n');
		    
		}
		System.out.println(sb.toString());

	}
}
